import * as Alchemy from 'alchemy'
import * as Cloudflare from 'alchemy/Cloudflare'
import * as Effect from 'effect/Effect'
import * as Layer from 'effect/Layer'
import {
  createHarborPlatformCloudflareStackDeclaration,
  harborPlatformCloudflareBindingNames,
  resolveHarborPlatformCloudflareResourceIds,
  validateHarborPlatformCloudflareStackDeclaration,
  type HarborPlatformCloudflareBindingNameOptions,
  type HarborPlatformCloudflareResourceIdOptions,
  type HarborPlatformCloudflareStackDeclaration,
  type HarborPlatformCloudflareWorkflowDeclarations,
  type HarborPlatformCloudflareWorkflowKey,
  type HarborPlatformCloudflareWorkflowOptions,
} from './stack'

export interface HarborPlatformCloudflareApiWorkerOptions {
  readonly main: string
  readonly props?:
    | Omit<Cloudflare.WorkerProps<Cloudflare.WorkerBindingProps>, 'main' | 'bindings'>
    | undefined
  readonly bindings?: Cloudflare.WorkerBindingProps | undefined
}

export interface HarborPlatformAlchemyCloudflareStackOptions {
  readonly stackName: string
  readonly bindingNames?: HarborPlatformCloudflareBindingNameOptions | undefined
  readonly resourceIds?: HarborPlatformCloudflareResourceIdOptions | undefined
  readonly database?: Cloudflare.DatabaseProps | undefined
  readonly artifactBucket?: Cloudflare.R2BucketProps | undefined
  readonly cacheNamespace?: Cloudflare.KVNamespaceProps | undefined
  readonly apiWorker: HarborPlatformCloudflareApiWorkerOptions
  readonly workflows?: HarborPlatformCloudflareWorkflowDeclarations | undefined
}

export interface HarborPlatformWorkflowStackOutput {
  readonly workflowId: Alchemy.Output<string>
  readonly workflowName: Alchemy.Output<string>
  readonly className: Alchemy.Output<string>
}

export interface HarborPlatformAlchemyCloudflareStackOutput {
  readonly declaration: HarborPlatformCloudflareStackDeclaration
  readonly apiWorker: {
    readonly workerId: Alchemy.Output<string>
    readonly workerName: Alchemy.Output<string>
    readonly url?: Alchemy.Output<string | undefined> | undefined
  }
  readonly database: {
    readonly databaseId: Alchemy.Output<string>
    readonly databaseName: Alchemy.Output<string>
  }
  readonly artifactBucket: {
    readonly bucketName: Alchemy.Output<string>
  }
  readonly cacheNamespace: {
    readonly namespaceId: Alchemy.Output<string>
    readonly title: Alchemy.Output<string>
  }
  readonly workflows: Partial<
    Record<HarborPlatformCloudflareWorkflowKey, HarborPlatformWorkflowStackOutput>
  >
}

const assertValidDeclaration = (declaration: HarborPlatformCloudflareStackDeclaration): void => {
  const validation = validateHarborPlatformCloudflareStackDeclaration(declaration)
  if (!validation.ok) {
    throw new Error(
      'Invalid Harbor platform Cloudflare stack declaration: ' + validation.errors.join('; ')
    )
  }
}

const workflowBindingName = (
  bindingNames: ReturnType<typeof harborPlatformCloudflareBindingNames>,
  key: HarborPlatformCloudflareWorkflowKey
): string | undefined => {
  if (key === 'harborExec') return bindingNames.harborExecWorkflow
  if (key === 'toolIndex') return bindingNames.toolIndexWorkflow
  return bindingNames.openApiImportWorkflow
}

const workflowResourceId = (
  resourceIds: ReturnType<typeof resolveHarborPlatformCloudflareResourceIds>,
  key: HarborPlatformCloudflareWorkflowKey
): string => {
  if (key === 'harborExec') return resourceIds.harborExecWorkflow
  if (key === 'toolIndex') return resourceIds.toolIndexWorkflow
  return resourceIds.openApiImportWorkflow
}

const workflowEntries = (
  workflows: HarborPlatformCloudflareWorkflowDeclarations | undefined
): ReadonlyArray<
  readonly [HarborPlatformCloudflareWorkflowKey, HarborPlatformCloudflareWorkflowOptions]
> =>
  Object.entries(workflows ?? {}) as ReadonlyArray<
    readonly [HarborPlatformCloudflareWorkflowKey, HarborPlatformCloudflareWorkflowOptions]
  >

export function createHarborPlatformCloudflareStack(
  options: HarborPlatformAlchemyCloudflareStackOptions
) {
  const declaration = createHarborPlatformCloudflareStackDeclaration({
    stackName: options.stackName,
    bindingNames: options.bindingNames,
    resourceIds: options.resourceIds,
    apiWorker: {
      main: options.apiWorker.main,
    },
    workflows: options.workflows,
  })
  assertValidDeclaration(declaration)

  const bindingNames = harborPlatformCloudflareBindingNames(options.bindingNames)
  const resourceIds = resolveHarborPlatformCloudflareResourceIds(
    options.stackName,
    options.resourceIds
  )

  return Alchemy.Stack(
    options.stackName,
    {
      providers: Layer.merge(Cloudflare.providers(), Cloudflare.WorkflowProvider()),
      state: Cloudflare.state(),
    },
    Effect.gen(function* () {
      const database = yield* Cloudflare.D1Database(resourceIds.database, options.database ?? {})
      const artifactBucket = yield* Cloudflare.R2Bucket(
        resourceIds.artifactBucket,
        options.artifactBucket ?? {}
      )
      const cacheNamespace = yield* Cloudflare.KVNamespace(
        resourceIds.cacheNamespace,
        options.cacheNamespace ?? {}
      )

      const bindings: Cloudflare.WorkerBindingProps = {
        ...(options.apiWorker.bindings ?? {}),
        [bindingNames.database]: database,
        [bindingNames.artifactBucket]: artifactBucket,
        [bindingNames.cacheNamespace]: cacheNamespace,
      }

      const apiWorker = yield* Cloudflare.Worker(resourceIds.apiWorker, {
        ...(options.apiWorker.props ?? {}),
        main: options.apiWorker.main,
        bindings,
      })

      const workflowOutputs: Partial<
        Record<HarborPlatformCloudflareWorkflowKey, HarborPlatformWorkflowStackOutput>
      > = {}
      for (const [key, workflow] of workflowEntries(options.workflows)) {
        const bindingName = workflowBindingName(bindingNames, key)
        if (!bindingName) continue
        yield* apiWorker.bind`${bindingName}`({
          bindings: [
            {
              type: 'workflow',
              name: bindingName,
              workflowName: workflow.workflowName,
              className: workflow.className,
            },
          ],
        })
        const workflowResource = yield* Cloudflare.WorkflowResource(
          workflowResourceId(resourceIds, key),
          {
            workflowName: workflow.workflowName,
            className: workflow.className,
            scriptName: apiWorker.workerName,
          }
        )
        workflowOutputs[key] = {
          workflowId: workflowResource.workflowId,
          workflowName: workflowResource.workflowName,
          className: workflowResource.className,
        }
      }

      return {
        declaration,
        apiWorker: {
          workerId: apiWorker.workerId,
          workerName: apiWorker.workerName,
          url: apiWorker.url,
        },
        database: {
          databaseId: database.databaseId,
          databaseName: database.databaseName,
        },
        artifactBucket: {
          bucketName: artifactBucket.bucketName,
        },
        cacheNamespace: {
          namespaceId: cacheNamespace.namespaceId,
          title: cacheNamespace.title,
        },
        workflows: workflowOutputs,
      } satisfies HarborPlatformAlchemyCloudflareStackOutput
    })
  )
}
