export interface HarborPlatformCloudflareBindingNameOptions {
  readonly database?: string | undefined
  readonly artifactBucket?: string | undefined
  readonly cacheNamespace?: string | undefined
  readonly harborExecWorkflow?: string | undefined
  readonly toolIndexWorkflow?: string | undefined
  readonly openApiImportWorkflow?: string | undefined
  readonly sessionsObject?: string | undefined
}

export interface HarborPlatformCloudflareBindingNames {
  readonly database: string
  readonly artifactBucket: string
  readonly cacheNamespace: string
  readonly harborExecWorkflow?: string | undefined
  readonly toolIndexWorkflow?: string | undefined
  readonly openApiImportWorkflow?: string | undefined
  readonly sessionsObject?: string | undefined
}

export interface HarborPlatformCloudflareResourceIdOptions {
  readonly apiWorker?: string | undefined
  readonly database?: string | undefined
  readonly artifactBucket?: string | undefined
  readonly cacheNamespace?: string | undefined
  readonly harborExecWorkflow?: string | undefined
  readonly toolIndexWorkflow?: string | undefined
  readonly openApiImportWorkflow?: string | undefined
  readonly sessionsObject?: string | undefined
}

export interface ResolvedHarborPlatformCloudflareResourceIds {
  readonly apiWorker: string
  readonly database: string
  readonly artifactBucket: string
  readonly cacheNamespace: string
  readonly harborExecWorkflow: string
  readonly toolIndexWorkflow: string
  readonly openApiImportWorkflow: string
  readonly sessionsObject: string
}

export interface HarborPlatformCloudflareApiWorkerDeclarationOptions {
  readonly main: string
}

export interface HarborPlatformCloudflareWorkflowOptions {
  readonly workflowName: string
  readonly className: string
}

export interface HarborPlatformCloudflareWorkflowDeclarations {
  readonly harborExec?: HarborPlatformCloudflareWorkflowOptions | undefined
  readonly toolIndex?: HarborPlatformCloudflareWorkflowOptions | undefined
  readonly openApiImport?: HarborPlatformCloudflareWorkflowOptions | undefined
}

export type HarborPlatformCloudflareWorkflowKey = 'harborExec' | 'toolIndex' | 'openApiImport'

export type HarborPlatformCloudflareResourceKind =
  | 'worker'
  | 'd1_database'
  | 'r2_bucket'
  | 'kv_namespace'
  | 'workflow'
  | 'durable_object_namespace'

export interface HarborPlatformCloudflareResourceDeclaration {
  readonly id: string
  readonly kind: HarborPlatformCloudflareResourceKind
  readonly binding?: string | undefined
  readonly metadata?: Record<string, string> | undefined
}

export interface HarborPlatformCloudflareStackSpec {
  readonly name: string
  readonly bindings: HarborPlatformCloudflareBindingNames
}

export interface HarborPlatformCloudflareStackDeclarationOptions {
  readonly stackName: string
  readonly bindingNames?: HarborPlatformCloudflareBindingNameOptions | undefined
  readonly resourceIds?: HarborPlatformCloudflareResourceIdOptions | undefined
  readonly apiWorker: HarborPlatformCloudflareApiWorkerDeclarationOptions
  readonly workflows?: HarborPlatformCloudflareWorkflowDeclarations | undefined
}

export interface HarborPlatformCloudflareStackDeclaration {
  readonly spec: HarborPlatformCloudflareStackSpec
  readonly resources: {
    readonly apiWorker: HarborPlatformCloudflareResourceDeclaration
    readonly database: HarborPlatformCloudflareResourceDeclaration
    readonly artifactBucket: HarborPlatformCloudflareResourceDeclaration
    readonly cacheNamespace: HarborPlatformCloudflareResourceDeclaration
    readonly workflows: Partial<
      Record<HarborPlatformCloudflareWorkflowKey, HarborPlatformCloudflareResourceDeclaration>
    >
    readonly sessionsObject?: HarborPlatformCloudflareResourceDeclaration | undefined
  }
  readonly requiredBindings: ReadonlyArray<string>
  readonly warnings: ReadonlyArray<string>
}

export interface HarborPlatformCloudflareStackValidation {
  readonly ok: boolean
  readonly errors: ReadonlyArray<string>
  readonly warnings: ReadonlyArray<string>
}

export const defaultHarborPlatformCloudflareBindingNames: HarborPlatformCloudflareBindingNames = {
  database: 'DB',
  artifactBucket: 'BUCKET',
  cacheNamespace: 'KV',
  harborExecWorkflow: 'HARBOR_EXEC_WORKFLOW',
  toolIndexWorkflow: 'TOOL_INDEX_WORKFLOW',
  openApiImportWorkflow: 'OPENAPI_IMPORT_WORKFLOW',
}

export function harborPlatformCloudflareBindingNames(
  overrides: HarborPlatformCloudflareBindingNameOptions = {}
): HarborPlatformCloudflareBindingNames {
  return {
    database: overrides.database ?? defaultHarborPlatformCloudflareBindingNames.database,
    artifactBucket:
      overrides.artifactBucket ?? defaultHarborPlatformCloudflareBindingNames.artifactBucket,
    cacheNamespace:
      overrides.cacheNamespace ?? defaultHarborPlatformCloudflareBindingNames.cacheNamespace,
    harborExecWorkflow: Object.hasOwn(overrides, 'harborExecWorkflow')
      ? overrides.harborExecWorkflow
      : defaultHarborPlatformCloudflareBindingNames.harborExecWorkflow,
    toolIndexWorkflow: Object.hasOwn(overrides, 'toolIndexWorkflow')
      ? overrides.toolIndexWorkflow
      : defaultHarborPlatformCloudflareBindingNames.toolIndexWorkflow,
    openApiImportWorkflow: Object.hasOwn(overrides, 'openApiImportWorkflow')
      ? overrides.openApiImportWorkflow
      : defaultHarborPlatformCloudflareBindingNames.openApiImportWorkflow,
    sessionsObject: Object.hasOwn(overrides, 'sessionsObject')
      ? overrides.sessionsObject
      : defaultHarborPlatformCloudflareBindingNames.sessionsObject,
  }
}

export function createHarborPlatformCloudflareStackSpec(
  options: Pick<HarborPlatformCloudflareStackDeclarationOptions, 'stackName' | 'bindingNames'>
): HarborPlatformCloudflareStackSpec {
  return {
    name: options.stackName,
    bindings: harborPlatformCloudflareBindingNames(options.bindingNames),
  }
}

export const defaultHarborPlatformCloudflareResourceIds = (
  stackName: string
): ResolvedHarborPlatformCloudflareResourceIds => ({
  apiWorker: stackName + '-api',
  database: stackName + '-db',
  artifactBucket: stackName + '-artifacts',
  cacheNamespace: stackName + '-kv',
  harborExecWorkflow: stackName + '-exec-workflow',
  toolIndexWorkflow: stackName + '-tool-index-workflow',
  openApiImportWorkflow: stackName + '-openapi-import-workflow',
  sessionsObject: stackName + '-sessions',
})

export const resolveHarborPlatformCloudflareResourceIds = (
  stackName: string,
  overrides: HarborPlatformCloudflareResourceIdOptions = {}
): ResolvedHarborPlatformCloudflareResourceIds => {
  const defaults = defaultHarborPlatformCloudflareResourceIds(stackName)
  return {
    apiWorker: overrides.apiWorker ?? defaults.apiWorker,
    database: overrides.database ?? defaults.database,
    artifactBucket: overrides.artifactBucket ?? defaults.artifactBucket,
    cacheNamespace: overrides.cacheNamespace ?? defaults.cacheNamespace,
    harborExecWorkflow: overrides.harborExecWorkflow ?? defaults.harborExecWorkflow,
    toolIndexWorkflow: overrides.toolIndexWorkflow ?? defaults.toolIndexWorkflow,
    openApiImportWorkflow: overrides.openApiImportWorkflow ?? defaults.openApiImportWorkflow,
    sessionsObject: overrides.sessionsObject ?? defaults.sessionsObject,
  }
}

const workflowBindingName = (
  bindings: HarborPlatformCloudflareBindingNames,
  key: HarborPlatformCloudflareWorkflowKey
): string | undefined => {
  if (key === 'harborExec') return bindings.harborExecWorkflow
  if (key === 'toolIndex') return bindings.toolIndexWorkflow
  return bindings.openApiImportWorkflow
}

const workflowResourceId = (
  resources: ResolvedHarborPlatformCloudflareResourceIds,
  key: HarborPlatformCloudflareWorkflowKey
): string => {
  if (key === 'harborExec') return resources.harborExecWorkflow
  if (key === 'toolIndex') return resources.toolIndexWorkflow
  return resources.openApiImportWorkflow
}

const definedBindingNames = (
  bindings: HarborPlatformCloudflareBindingNames
): ReadonlyArray<string> =>
  [
    bindings.database,
    bindings.artifactBucket,
    bindings.cacheNamespace,
    bindings.harborExecWorkflow,
    bindings.toolIndexWorkflow,
    bindings.openApiImportWorkflow,
    bindings.sessionsObject,
  ].filter((binding): binding is string => typeof binding === 'string' && binding.length > 0)

const duplicateValues = (values: ReadonlyArray<string>): ReadonlyArray<string> => {
  const seen = new Set<string>()
  const duplicates = new Set<string>()
  for (const value of values) {
    if (seen.has(value)) duplicates.add(value)
    seen.add(value)
  }
  return Array.from(duplicates).sort()
}

export function createHarborPlatformCloudflareStackDeclaration(
  options: HarborPlatformCloudflareStackDeclarationOptions
): HarborPlatformCloudflareStackDeclaration {
  const spec = createHarborPlatformCloudflareStackSpec(options)
  const resourceIds = resolveHarborPlatformCloudflareResourceIds(
    options.stackName,
    options.resourceIds
  )
  const workflowEntries = Object.entries(options.workflows ?? {}) as ReadonlyArray<
    readonly [HarborPlatformCloudflareWorkflowKey, HarborPlatformCloudflareWorkflowOptions]
  >
  const workflowResources: Partial<
    Record<HarborPlatformCloudflareWorkflowKey, HarborPlatformCloudflareResourceDeclaration>
  > = {}

  for (const [key, workflow] of workflowEntries) {
    const binding = workflowBindingName(spec.bindings, key)
    workflowResources[key] = {
      id: workflowResourceId(resourceIds, key),
      kind: 'workflow',
      binding,
      metadata: {
        workflowName: workflow.workflowName,
        className: workflow.className,
      },
    }
  }

  const requiredBindings = [
    spec.bindings.database,
    spec.bindings.artifactBucket,
    spec.bindings.cacheNamespace,
    ...workflowEntries.flatMap(([key]) => {
      const binding = workflowBindingName(spec.bindings, key)
      return binding ? [binding] : []
    }),
    ...(spec.bindings.sessionsObject ? [spec.bindings.sessionsObject] : []),
  ]

  const warnings = [
    ...(spec.bindings.sessionsObject
      ? [
          'sessionsObject declares a future Durable Object binding; platform-cloudflare does not provision the namespace yet.',
        ]
      : []),
  ]

  return {
    spec,
    resources: {
      apiWorker: {
        id: resourceIds.apiWorker,
        kind: 'worker',
        metadata: {
          main: options.apiWorker.main,
        },
      },
      database: {
        id: resourceIds.database,
        kind: 'd1_database',
        binding: spec.bindings.database,
      },
      artifactBucket: {
        id: resourceIds.artifactBucket,
        kind: 'r2_bucket',
        binding: spec.bindings.artifactBucket,
      },
      cacheNamespace: {
        id: resourceIds.cacheNamespace,
        kind: 'kv_namespace',
        binding: spec.bindings.cacheNamespace,
      },
      workflows: workflowResources,
      ...(spec.bindings.sessionsObject
        ? {
            sessionsObject: {
              id: resourceIds.sessionsObject,
              kind: 'durable_object_namespace' as const,
              binding: spec.bindings.sessionsObject,
            },
          }
        : {}),
    },
    requiredBindings,
    warnings,
  }
}

export function validateHarborPlatformCloudflareStackDeclaration(
  declaration: HarborPlatformCloudflareStackDeclaration
): HarborPlatformCloudflareStackValidation {
  const errors: string[] = []
  const warnings = [...declaration.warnings]

  if (declaration.spec.name.trim().length === 0) {
    errors.push('stackName must be a non-empty string.')
  }

  const workerMain = declaration.resources.apiWorker.metadata?.main
  if (!workerMain || workerMain.trim().length === 0) {
    errors.push('apiWorker.main must be a non-empty path.')
  }

  const duplicateBindings = duplicateValues(definedBindingNames(declaration.spec.bindings))
  for (const binding of duplicateBindings) {
    errors.push('binding name must be unique: ' + binding)
  }

  const resourceIds = [
    declaration.resources.apiWorker.id,
    declaration.resources.database.id,
    declaration.resources.artifactBucket.id,
    declaration.resources.cacheNamespace.id,
    ...Object.values(declaration.resources.workflows).map((resource) => resource.id),
    ...(declaration.resources.sessionsObject ? [declaration.resources.sessionsObject.id] : []),
  ]
  for (const id of duplicateValues(resourceIds)) {
    errors.push('resource id must be unique: ' + id)
  }

  for (const [key, resource] of Object.entries(declaration.resources.workflows)) {
    if (!resource.binding) {
      errors.push(key + ' workflow resource requires a workflow binding name.')
    }
  }

  if (declaration.requiredBindings.length === 0) {
    errors.push('at least one platform binding must be declared.')
  }

  return {
    ok: errors.length === 0,
    errors,
    warnings,
  }
}
